"""JSON batch entry point; policy/runtime modules implement the system.

Reads exactly one request object from stdin, replays every structurally valid
job and writes exactly one response object to stdout.  All whole-request
strictness (encoding, duplicate keys, nonfinite numbers, integer token length,
container nesting, top level schema and the batch budgets) is enforced before
any job is replayed; malformed job contents stay job scoped.
"""
import json
import math
import os
import re
import sys

from ebpf.helper import Agent, OK, ERR, STATE, ALLOW, WIRE, STAGE, INSPECT
from syntax import parse as parse_policy

U32 = 4294967295
LABEL_MAX = 4294967294
MAX_INPUT = 24 * 1048576
MAX_JOBS = 4
MAX_EVENTS = 200000
MAX_STAGES = 16
MAX_POLICY_BYTES = 8 * 1048576
MAX_ATOMS = 32768
MAX_SYMBOLS = 65536
MAX_NESTING = 64
MAX_WIRE = 96

LIMITS = (('images', 16), ('cells', 262144), ('units', 1024),
          ('contexts', 32768), ('connections', 4096), ('packets', 32768),
          ('files', 8192))

# op -> required fields with their static type kind
POS, NAME, TEXT, WIRE_T, PAIR, UNIT = 0, 1, 2, 3, 4, 5
SCHEMA = {
    'stage': (('epoch', POS), ('policy', TEXT)),
    'commit': (('epoch', POS),),
    'retire': (('epoch', POS),),
    'spawn': (('unit', UNIT), ('service', NAME)),
    'clone': (('parent', UNIT), ('child', UNIT)),
    'exit': (('unit', UNIT),),
    'begin': (('unit', UNIT), ('rid', POS)),
    'finish': (('unit', UNIT), ('rid', POS)),
    'open': (('connection', PAIR),),
    'close': (('connection', PAIR),),
    'send': (('unit', UNIT), ('rid', POS), ('connection', PAIR),
             ('stream', POS), ('destination', NAME)),
    'recv': (('unit', UNIT), ('rid', POS), ('connection', PAIR),
             ('stream', POS), ('wire', WIRE_T)),
    'store': (('unit', UNIT), ('rid', POS), ('file', PAIR)),
    'load': (('file', PAIR), ('unit', UNIT), ('rid', POS)),
    'unlink': (('file', PAIR),),
    'inspect': (),
}

_NAME_RE = re.compile(r'[A-Za-z][A-Za-z0-9]{0,23}\Z')
_name_cache = {}
_STRING = re.compile(r'"(?:[^"\\]|\\.)*"')
_BRACKET = re.compile(r'[\[\]{}]')
_dumps = json.dumps


class Invalid(ValueError):
    """Whole-request or job level structural violation."""


# --------------------------------------------------------------------------
# JSON envelope
# --------------------------------------------------------------------------
def _pairs(pairs):
    seen = {}
    for key, value in pairs:
        if key in seen:
            raise Invalid('duplicate key')
        seen[key] = value
    return seen


def _constant(token):
    raise Invalid('nonfinite number')


def _float(token):
    value = float(token)
    if not math.isfinite(value):
        raise Invalid('nonfinite number')
    return value


def _nesting(text):
    """Container nesting limit; strings (even with brackets) contribute none."""
    stripped = _STRING.sub('S', text)
    depth = 0
    for ch in _BRACKET.findall(stripped):
        if ch == '[' or ch == '{':
            depth += 1
            if depth > MAX_NESTING:
                raise Invalid('nesting')
        else:
            depth -= 1


def decode(data):
    if len(data) > MAX_INPUT:
        raise Invalid('size')
    try:
        text = data.decode('utf-8')
    except UnicodeDecodeError:
        raise Invalid('encoding')
    try:
        request = json.loads(text, object_pairs_hook=_pairs,
                             parse_constant=_constant, parse_float=_float)
    except Invalid:
        raise
    except Exception:
        raise Invalid('json')
    _nesting(text)
    if type(request) is not dict or len(request) != 1:
        raise Invalid('schema')
    jobs = request.get('jobs')
    if type(jobs) is not list or len(jobs) > MAX_JOBS:
        raise Invalid('schema')
    return jobs


# --------------------------------------------------------------------------
# static job validation
# --------------------------------------------------------------------------
def _is_name(value):
    if type(value) is not str:
        return False
    got = _name_cache.get(value)
    if got is None:
        got = len(value) <= 24 and _NAME_RE.match(value) is not None
        if len(_name_cache) > 8192:
            _name_cache.clear()
        _name_cache[value] = got
    return got


def _is_u32(value, low=1):
    return type(value) is int and low <= value <= U32


def _is_pair(value):
    if type(value) is not list or len(value) != 2:
        return False
    return _is_u32(value[0]) and _is_u32(value[1])


def _is_unit(value):
    if type(value) is not list or len(value) != 3:
        return False
    return (_is_u32(value[0], 0) and _is_u32(value[1]) and _is_u32(value[2]))


def validate(job):
    """Static job validation.

    Returns ``(policy_bytes, stages, atoms, symbols, parsed)`` where ``parsed``
    maps the index of every syntactically valid stage event to its parse
    result, so replay never parses the same string twice.
    """
    if type(job) is not dict or len(job) != 3:
        raise Invalid('job')
    services = job.get('services')
    limits = job.get('limits')
    events = job.get('events')
    if type(services) is not list:
        raise Invalid('services')
    count = len(services)
    if count < 1 or count > 16:
        raise Invalid('services')
    names = set()
    labels = set()
    for service in services:
        if type(service) is not dict or len(service) != 2:
            raise Invalid('service')
        name = service.get('name')
        label = service.get('label')
        if not _is_name(name):
            raise Invalid('name')
        if not _is_u32(label) or label > LABEL_MAX:
            raise Invalid('label')
        if name in names or label in labels:
            raise Invalid('duplicate')
        names.add(name)
        labels.add(label)
    if type(limits) is not dict or len(limits) != len(LIMITS):
        raise Invalid('limits')
    for key, top in LIMITS:
        value = limits.get(key)
        if type(value) is not int or value < 1 or value > top:
            raise Invalid('limits')
    if type(events) is not list or len(events) > MAX_EVENTS:
        raise Invalid('events')
    policy_bytes = 0
    stages = 0
    atoms = 0
    symbols = 0
    parsed = {}
    index = 0
    for event in events:
        if type(event) is not dict:
            raise Invalid('event')
        op = event.get('op')
        spec = SCHEMA.get(op) if type(op) is str else None
        if spec is None or len(event) != len(spec) + 1:
            raise Invalid('event')
        for key, kind in spec:
            if key not in event:
                raise Invalid('field')
            value = event[key]
            if kind == POS:
                if not _is_u32(value):
                    raise Invalid('field')
            elif kind == NAME:
                if not _is_name(value):
                    raise Invalid('field')
            elif kind == TEXT:
                if type(value) is not str:
                    raise Invalid('field')
                try:
                    policy_bytes += len(value.encode('utf-8'))
                except UnicodeEncodeError:
                    raise Invalid('field')
            elif kind == WIRE_T:
                if value is not None and (type(value) is not str
                                          or len(value) > MAX_WIRE):
                    raise Invalid('field')
            elif kind == PAIR:
                if not _is_pair(value):
                    raise Invalid('field')
            elif not _is_unit(value):
                raise Invalid('field')
        if op == 'stage':
            stages += 1
            try:
                result = parse_policy(event['policy'])
            except Exception:
                result = None
            if result is not None:
                atoms += result.atoms
                symbols += result.symbols
                parsed[index] = result
        index += 1
    return policy_bytes, stages, atoms, symbols, parsed


# --------------------------------------------------------------------------
# outcome serialisation (compact, ASCII only)
# --------------------------------------------------------------------------
_B_OK = b'{"ok":true}'
_B_ERR = b'{"error":"rejected"}'
_B_ALLOW_T = b'{"ok":true,"allow":true}'
_B_ALLOW_F = b'{"ok":true,"allow":false}'


def serialize(outcome):
    tag = outcome[0]
    if tag == OK:
        return _B_OK
    if tag == ERR:
        return _B_ERR
    if tag == STATE:
        return b'{"ok":true,"epoch":%d,"state":%d}' % (outcome[1], outcome[2])
    if tag == ALLOW:
        return _B_ALLOW_T if outcome[1] else _B_ALLOW_F
    if tag == WIRE:
        return b'{"ok":true,"wire":"' + outcome[1].encode() + b'"}'
    if tag == STAGE:
        head = b'{"ok":true,"epoch":%d,"image":' % outcome[1]
        return head + _dumps(outcome[2], separators=(',', ':')).encode() + b'}'
    return _dumps({'ok': True, 'active': outcome[1], 'images': outcome[2],
                   'units': outcome[3], 'contexts': outcome[4],
                   'connections': outcome[5], 'packets': outcome[6],
                   'files': outcome[7]}, separators=(',', ':')).encode()


class Writer(object):
    """Bounded chunked writer for the single response object."""

    def __init__(self, stream, chunk=1 << 20):
        self.stream = stream
        self.chunk = chunk
        self.parts = []
        self.size = 0

    def push(self, block):
        self.parts.append(block)
        self.size += len(block)
        if self.size >= self.chunk:
            self.flush()

    def flush(self):
        if self.parts:
            self.stream.write(b''.join(self.parts))
            self.parts = []
            self.size = 0


def replay(job, parsed, writer):
    agent = Agent(job['services'], job['limits'])
    dispatch = agent.event
    push = writer.push
    index = 0
    for event in job['events']:
        try:
            outcome = dispatch(event, parsed.get(index))
        except Exception:
            outcome = (ERR,)
        push(serialize(outcome))
        push(b',')
        index += 1


def run(data, writer):
    try:
        jobs = decode(data)
    except Invalid:
        writer.push(b'{"error":"invalid"}')
        return
    except Exception:
        writer.push(b'{"error":"invalid"}')
        return
    states = []
    total_events = 0
    total_bytes = 0
    total_stages = 0
    total_atoms = 0
    total_symbols = 0
    for job in jobs:
        try:
            policy_bytes, stages, atoms, symbols, parsed = validate(job)
        except Invalid:
            states.append(None)
            continue
        except Exception:
            states.append(None)
            continue
        total_events += len(job['events'])
        total_bytes += policy_bytes
        total_stages += stages
        total_atoms += atoms
        total_symbols += symbols
        states.append(parsed)
    if (total_events > MAX_EVENTS or total_bytes > MAX_POLICY_BYTES
            or total_stages > MAX_STAGES or total_atoms > MAX_ATOMS
            or total_symbols > MAX_SYMBOLS):
        writer.push(b'{"error":"invalid"}')
        return
    writer.push(b'{"results":[')
    first = True
    for job, parsed in zip(jobs, states):
        if not first:
            writer.push(b',')
        first = False
        if parsed is None:
            writer.push(b'{"error":"invalid"}')
            continue
        writer.push(b'{"events":[')
        try:
            replay(job, parsed, writer)
        except Exception:
            writer.push(b'{"error":"rejected"},')
        if writer.parts and writer.parts[-1] == b',':
            writer.parts.pop()
            writer.size -= 1
        writer.push(b']}')
    writer.push(b']}')


def main():
    out = Writer(sys.stdout.buffer)
    try:
        data = sys.stdin.buffer.read(MAX_INPUT + 1)
    except Exception:
        data = b''
    try:
        run(data, out)
    except Exception:
        out.parts = []
        out.size = 0
        out.push(b'{"error":"invalid"}')
    out.flush()
    try:
        sys.stdout.buffer.flush()
        sys.stdout.flush()
    except Exception:
        pass
    os._exit(0)


if __name__ == '__main__':
    main()
